import{_ as t,o,c as r,a4 as s}from"./chunks/framework.ClGzHnIj.js";const m=JSON.parse('{"title":"Observatoire des Protocoles","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://lognebudo.github.io/llmxray/docs/fr/guide/protocols.html"}]]},"headers":[],"relativePath":"fr/guide/protocols.md","filePath":"fr/guide/protocols.md","lastUpdated":1791987481000}'),n={name:"fr/guide/protocols.md"};function a(l,e,d,i,c,u){return o(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="observatoire-des-protocoles" tabindex="-1">Observatoire des Protocoles <a class="header-anchor" href="#observatoire-des-protocoles" aria-label="Permalink to &quot;Observatoire des Protocoles&quot;">​</a></h1><p>L&#39;<strong>Observatoire des Protocoles</strong> envoie le même prompt à travers <strong>trois protocoles de service différents</strong> sur votre démon Ollama local, en parallèle, et vous montre exactement comment chacun cadre la même conversation.</p><p><strong>Élément de barre latérale :</strong> Observatoire de protocoles (sous Complétion de code) <strong>Route :</strong> <code>/protocols</code><strong>Ajouté dans :</strong> v0.4.7 (mai 2026)</p><h2 id="quel-est-l-interet" tabindex="-1">Quel est l&#39;intérêt ? <a class="header-anchor" href="#quel-est-l-interet" aria-label="Permalink to &quot;Quel est l&#39;intérêt ?&quot;">​</a></h2><p>Ollama ne parle pas qu&#39;un seul protocole. Il expose en réalité le même modèle local à travers trois formats de fil différents :</p><table tabindex="0"><thead><tr><th>Endpoint</th><th>Format</th><th>Encadrement du flux</th></tr></thead><tbody><tr><td><code>/api/chat</code></td><td>Ollama natif</td><td>NDJSON (un JSON par ligne)</td></tr><tr><td><code>/v1/chat/completions</code></td><td>Compatible OpenAI</td><td>SSE (<code>data: …</code>)</td></tr><tr><td><code>/v1/messages</code></td><td>Compatible Anthropic</td><td>SSE avec tags <code>event:</code></td></tr></tbody></table><p>Différents écosystèmes parlent aux LLMs via différents protocoles. Si vous construisez des intégrations, déboguez une bibliothèque cliente, ou êtes simplement curieux de voir comment le même modèle se comporte sous différents cadrages, cette page rend les différences visibles — <strong>le tout contre le même modèle local, sans cloud, sans clés API, sans inscription.</strong></p><h2 id="utilisation" tabindex="-1">Utilisation <a class="header-anchor" href="#utilisation" aria-label="Permalink to &quot;Utilisation&quot;">​</a></h2><ol><li>Choisissez un modèle dans la liste déroulante.</li><li>Tapez un prompt (un défaut est fourni).</li><li>Ajustez le nombre de tokens max si besoin.</li><li>Cliquez sur <strong>Lancer les 3 protocoles</strong>.</li></ol><p>Trois colonnes diffusent leurs réponses en parallèle. Chaque colonne affiche :</p><ul><li>Le <strong>nom du protocole</strong> et le chemin de l&#39;endpoint</li><li>Un <strong>badge de statut</strong> en direct (inactif → streaming → terminé)</li><li>Le <strong>texte de réponse streamé</strong></li><li>Une <strong>grille de métriques</strong> : TTFT, total ms, tokens, tokens/sec, motif de fin</li><li>Un panneau <strong>Inspecter l&#39;enveloppe</strong> dépliable montrant les chunks/événements bruts (premier et dernier)</li></ul><h2 id="l-onglet-diff-d-enveloppe" tabindex="-1">L&#39;onglet Diff d&#39;enveloppe <a class="header-anchor" href="#l-onglet-diff-d-enveloppe" aria-label="Permalink to &quot;L&#39;onglet Diff d&#39;enveloppe&quot;">​</a></h2><p>Une fois les trois runs terminés, une section inférieure à onglets apparaît. Passez sur <strong>Diff. d&#39;enveloppe</strong> pour voir une comparaison côte à côte de comment chaque protocole cadre ses réponses :</p><table tabindex="0"><thead><tr><th>Aspect</th><th>Natif</th><th>Compat. OpenAI</th><th>Compat. Anthropic</th></tr></thead><tbody><tr><td>Encadrement du flux</td><td>NDJSON</td><td>SSE</td><td>SSE avec tags <code>event:</code></td></tr><tr><td>Porteur du motif de fin</td><td><code>done</code> + <code>done_reason</code></td><td><code>choices[].finish_reason</code></td><td>événement <code>message_stop</code></td></tr><tr><td>Porteur du compte de tokens</td><td><code>eval_count</code> + <code>prompt_eval_count</code></td><td><code>usage.{prompt,completion,total}_tokens</code></td><td><code>usage.{input,output}_tokens</code></td></tr><tr><td>Porteur du cache d&#39;invite</td><td><code>prompt_eval_cached_count</code></td><td><code>usage.prompt_tokens_details.cached_tokens</code></td><td><code>usage.cache_read_input_tokens</code></td></tr><tr><td>Porteur du temps de préremplissage</td><td><code>prompt_eval_duration</code> (ns)</td><td><code>timings.prompt_ms</code></td><td>—</td></tr><tr><td>Porteur du raisonnement</td><td><code>message.thinking</code></td><td><code>choices[].delta.reasoning</code></td><td>événement <code>thinking_delta</code></td></tr><tr><td>Enveloppe d&#39;erreur</td><td><code>{&quot;error&quot;: &quot;string&quot;}</code></td><td><code>{&quot;error&quot;: {&quot;message&quot;, &quot;type&quot;, &quot;code&quot;}}</code></td><td><code>{&quot;type&quot;: &quot;error&quot;, &quot;error&quot;: {...}, &quot;request_id&quot;}</code></td></tr></tbody></table><p>Les lignes « ce run » se remplissent avec les valeurs réellement observées pendant votre exécution — vous pouvez voir, par exemple, que le protocole natif a renvoyé <code>done_reason: &quot;stop&quot;</code> tandis que le protocole Anthropic a appelé le même résultat <code>stop_reason: &quot;end_turn&quot;</code>.</p><p>Avec un modèle à raisonnement, la ligne du raisonnement est celle à surveiller. Le chemin natif ne réfléchit que si la requête le demande ; les deux chemins compatibles laissent le modèle réfléchir par défaut, et ce raisonnement partage le budget de sortie avec la réponse. Avec la même invite et le même <code>max_tokens</code>, une colonne compatible peut dépenser tous ses tokens en raisonnement et ne produire aucun texte de réponse. Chaque colonne montre ce que le modèle a pensé, et le dit quand le budget s&#39;est épuisé avant le premier mot.</p><h3 id="les-deux-debits-de-preremplissage" tabindex="-1">Les deux débits de préremplissage <a class="header-anchor" href="#les-deux-debits-de-preremplissage" aria-label="Permalink to &quot;Les deux débits de préremplissage&quot;">​</a></h3><p>Depuis Ollama 0.35.1, l&#39;endpoint compatible OpenAI joint un bloc <code>timings</code> avec un <code>prompt_per_second</code> tout calculé. Le tableau l&#39;affiche comme <strong>« Débit de préremplissage, tel que le démon l&#39;annonce »</strong>, à côté de <strong>« Débit de préremplissage sur les tokens évalués »</strong>, que LLMxRay calcule à partir du même chunk : <code>(prompt_tokens − cached_tokens) / prompt_ms</code>.</p><p>Ils divergent dès que le cache est chaud. Le chiffre du démon divise l&#39;invite <em>totale</em> par le temps passé sur les tokens <em>non mis en cache</em>, il est donc gonflé du taux de réutilisation ; lancez deux fois la même invite et la cellule annoncée passe en orange. Mesuré sur 0.40.3 avec 30 tokens sur 31 en cache : 3875 tok/s annoncés, 125 tok/s évalués. Seul le second chiffre décrit du travail réellement fait par le modèle. Le protocole natif n&#39;annonce jamais de débit, et le protocole compatible Anthropic ne rapporte aucun temps de préremplissage, d&#39;où les tirets.</p><h2 id="pourquoi-trois-protocoles" tabindex="-1">Pourquoi trois protocoles ? <a class="header-anchor" href="#pourquoi-trois-protocoles" aria-label="Permalink to &quot;Pourquoi trois protocoles ?&quot;">​</a></h2><p>Ce n&#39;est pas théorique — beaucoup d&#39;outils réels s&#39;appuient sur ces couches de compatibilité :</p><ul><li><strong>Compat. OpenAI</strong> est la façon dont les extensions IDE, Cursor, Continue.dev, et la plupart des bibliothèques Python qui s&#39;attendent à « l&#39;API OpenAI » parlent aux modèles locaux.</li><li><strong>Compat. Anthropic</strong> est la façon dont des outils comme Claude Code, Claude Cowork et OpenClaw parlent à Ollama (ajouté dans Ollama v0.23 / janvier 2026).</li><li><strong>Natif</strong> est ce qui donne les métriques les plus riches — incluant les temps, les comptes d&#39;évaluation et le champ <code>done_reason</code>.</li></ul><p>Si un outil tiers se comporte étrangement contre votre Ollama local, l&#39;Observatoire des Protocoles vous permet de voir à quoi ressemble le fil à travers les yeux de ce protocole.</p><h2 id="voir-aussi" tabindex="-1">Voir aussi <a class="header-anchor" href="#voir-aussi" aria-label="Permalink to &quot;Voir aussi&quot;">​</a></h2><ul><li><a href="./chat-diagnostics.html">Diagnostics de Chat</a> pour une analyse approfondie en mono-protocole</li><li><a href="./compare.html">Comparer</a> pour comparer différents <em>modèles</em> sur le même prompt (l&#39;Observatoire garde le modèle constant et varie le protocole)</li></ul>',25)])])}const h=t(n,[["render",a]]);export{m as __pageData,h as default};
